import math

def is_perfect_cube(n):
    if n == 0:
        return True
    # Calculate the nearest integer cube root
    # Use round(n**(1/3)) as an initial guess
    root = round(n**(1/3.0))

    # Check the root and its neighbors due to floating point inaccuracies
    for k in range(max(0, root - 2), root + 3):
        if k**3 == n:
            return True
        # If n is negative, we only care about negative roots
        if n < 0 and k**3 == n:
             return True
        if n < 0 and (-k)**3 == n:
             return True

    # A more robust integer check for perfect cubes:
    # Calculate the floor of the cube root
    if n > 0:
        k = int(n**(1/3.0))
        return k**3 == n
    elif n < 0:
        # For negative numbers, we check if -n is a perfect cube
        return (-int(-n)**(1/3.0))**3 == n

def P(x):
    return (8*x - 41) * (x + 3)**2

solutions = []
for x in range(-10, 11):
    value = P(x)
    # Using a slightly simplified check since the numbers are small, 
    # though the previous custom function was designed for robustness.
    # Let's rely on the standard math module check for this small range.
    cbrt_float = value**(1/3.0)
    cbrt_int = round(cbrt_float)

    if cbrt_int**3 == value:
        solutions.append((x, value, cbrt_int))

print("x | P(x) | Perfect Cube (k)")
for x, value, k in solutions:
    print(f"{x:2} | {value:4} | {k}")
